28	static int usage() {
29	    fprintf(stderr, "\n");
30	    fprintf(stderr, "Usage:   seqtk <command> <arguments>\n");
31	    fprintf(stderr, "Version: 1.5-r133\n\n");
32	    fprintf(stderr, "Command: seq       common transformation of FASTA/Q\n");
33	    fprintf(stderr, "         size      report the number sequences and bases\n");
34	    fprintf(stderr, "         comp      get the nucleotide composition of FASTA/Q\n");
35	    fprintf(stderr, "         sample    subsample sequences\n");
36	    fprintf(stderr, "         subseq    extract subsequences from FASTA/Q\n");
37	    fprintf(stderr, "         fqchk     fastq QC (base/quality summary)\n");
38	    fprintf(stderr, "         mergepe   interleave two PE FASTA/Q files\n");
39	    fprintf(stderr, "         split     split one file into multiple smaller files\n");
40	    fprintf(stderr, "         trimfq    trim FASTQ using the Phred algorithm\n");
41	    fprintf(stderr, "\n");
42	    fprintf(stderr, "         hety      regional heterozygosity\n");
43	    fprintf(stderr, "         gc        identify high- or low-GC regions\n");
44	    fprintf(stderr, "         mutfa     point mutate FASTA at specified positions\n");
45	    fprintf(stderr, "         mergefa   merge two FASTA/Q files\n");
46	    fprintf(stderr, "         famask    apply a X-coded FASTA to a source FASTA\n");
47	    fprintf(stderr, "         dropse    drop unpaired from interleaved PE FASTA/Q\n");
48	    fprintf(stderr, "         rename    rename sequence names\n");
49	    fprintf(stderr, "         randbase  choose a random base from hets\n");
50	    fprintf(stderr, "         cutN      cut sequence at long N\n");
51	    fprintf(stderr, "         gap       get the gap locations\n");
52	    fprintf(stderr, "         listhet   extract the position of each het\n");
53	    fprintf(stderr, "         hpc       homopolyer-compressed sequence\n");
54	    fprintf(stderr, "         telo      identify telomere repeats in asm or long reads\n");
55	    fprintf(stderr, "\n");
56	    return 1;
57	}
