59	int main(int argc, char** argv) {
60	    if (argc == 1) return usage();
61	    struct Cmd { const char* name; int (*fn)(int, char**); };
62	    static const Cmd cmds[] = {
63	        {"seq", cmd_seq}, {"size", cmd_size}, {"comp", cmd_comp},
64	        {"sample", cmd_sample}, {"subseq", cmd_subseq}, {"fqchk", cmd_fqchk},
65	        {"mergepe", cmd_mergepe}, {"split", cmd_split}, {"trimfq", cmd_trimfq},
66	        {"hety", cmd_hety}, {"gc", cmd_gc}, {"mutfa", cmd_mutfa},
67	        {"mergefa", cmd_mergefa}, {"famask", cmd_famask}, {"dropse", cmd_dropse},
68	        {"rename", cmd_rename}, {"randbase", cmd_randbase}, {"cutN", cmd_cutN},
69	        {"gap", cmd_gap}, {"listhet", cmd_listhet}, {"hpc", cmd_hpc},
70	        {"telo", cmd_telo},
71	    };
72	    for (const Cmd& c : cmds) {
73	        if (c.fn && strcmp(argv[1], c.name) == 0)
74	            return c.fn(argc - 1, argv + 1);
75	    }
76	    fprintf(stderr, "[main] unrecognized command '%s'. Abort!\n", argv[1]);
77	    return 1;
78	}
